// Show the passage around the first matched term, with every matched term highlighted.
function Snippet({text,query}:{text:string;query:string}){
 const terms=Array.from(new Set([query.trim(),...query.trim().split(/\s+/)].filter(t=>t.length>0))).sort((a,b)=>b.length-a.length);
 const lower=text.toLowerCase();let at=-1;for(const t of terms){const i=lower.indexOf(t.toLowerCase());if(i>=0&&(at<0||i<at))at=i}
 const start=at>80?at-80:0;const part=(start?'… ':'')+text.slice(start,start+320)+(start+320<text.length?' …':'');
 const esc=terms.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|');
 if(!esc)return <>{part}</>;
 const re=new RegExp('('+esc+')','gi');
 return <>{part.split(re).map((s,i)=>i%2?<mark key={i}>{s}</mark>:s)}</>;
}

function KnowledgeSearch({kbs,docs=[],onPreview}:{kbs:KB[];docs?:Doc[];onPreview:(id:string,context?:PreviewContext)=>void}){
 const router=useRouter();const urlQuery=useSearchParams().toString();
 const [q,setQ]=useState('');const [search,setSearch]=useState('');const [kb,setKb]=useState('');const [mode,setMode]=useState('hybrid');const [type,setType]=useState('');const [page,setPage]=useState(1);
 useEffect(()=>{const params=new URLSearchParams(urlQuery);setQ(params.get('q')||'');setSearch(params.get('q')||'');setKb(params.get('kb')||'');setPage(1)},[urlQuery]);
 const results=useQuery({queryKey:['search',search,kb,mode],queryFn:()=>api<Citation[]>(`/search?q=${encodeURIComponent(search)}&mode=${mode}${kb?'&kb_id='+kb:''}`),enabled:!!search});
 const pagesOf=new Map<string,number[]>();for(const r of results.data||[])pagesOf.set(r.document_id,[...new Set([...(pagesOf.get(r.document_id)||[]),r.page])].sort((a,b)=>a-b));const seen=new Set<string>();const found=(results.data||[]).filter(r=>{if(seen.has(r.document_id)||type&&!r.name.toLowerCase().endsWith(type))return false;seen.add(r.document_id);return true});
 const everything=docs.filter(d=>(!kb||d.knowledge_base_id===kb)&&(!type||d.name.toLowerCase().endsWith(type))).sort((a,b)=>b.created_at.localeCompare(a.created_at));const kbName=(id:string)=>localName(kbs.find(k=>k.id===id))||tr('เอกสารองค์กร');const sizeText=(n:number)=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
 return <><div className="card padded" style={{marginBottom:16}}><form className="prompt-box" onSubmit={e=>{e.preventDefault();setSearch(q.trim());setPage(1);const p=new URLSearchParams();p.set('q',q.trim());if(kb)p.set('kb',kb);router.replace('/knowledge/search?'+p.toString())}}><Search size={24}/><input value={q} onChange={e=>setQ(e.target.value)} aria-label={tr('คำค้นหา')} placeholder={tr('เช่น นโยบาย HR, แผนกลยุทธ์, คู่มือการใช้งาน...')} required/><Button type="submit" disabled={results.isFetching} aria-busy={results.isFetching}>{results.isFetching?<Loader2 size={19} className="animate-spin"/>:<Search size={19}/>}{results.isFetching?tr('กำลังค้นหา…'):tr('ค้นหา')}</Button></form></div><div className="search-filters"><div className="tabs studio-tabs" role="radiogroup" aria-label={tr('โหมดการค้นหา')}>{[['hybrid','Hybrid'],['keyword',tr('คำสำคัญ')],['semantic','Vector store']].map(([v,l])=><button key={v} type="button" role="radio" aria-checked={mode===v} className={mode===v?'selected':''} onClick={()=>setMode(v)}>{l}</button>)}</div><Sel aria-label={tr('คลังความรู้')} value={kb} onChange={e=>{setKb(e.target.value);setPage(1)}}><option value="">{tr('ทุกคลังความรู้')}</option>{kbs.map(k=><option key={k.id} value={k.id}>{localName(k)}</option>)}</Sel><Sel aria-label={tr('ประเภทไฟล์')} value={type} onChange={e=>{setType(e.target.value);setPage(1)}}><option value="">{tr('ทุกประเภทไฟล์')}</option>{['pdf','docx','doc','pptx','xlsx','xls','csv','txt','md','html','png','jpg','jpeg'].map(t=><option key={t} value={'.'+t}>{t}</option>)}</Sel></div>{search?results.isFetching?<SearchLoading/>:<><div className="section-heading"><h2>{tr('ผลการค้นหา')} <em>{found.length}</em> {tr('รายการ')}</h2><span className="muted small">{tr('เฉพาะเอกสารที่คุณมีสิทธิ์เข้าถึง')}</span></div>{found.length>0&&found.every(r=>(r as Citation&{approx?:boolean}).approx)&&<p className="muted small" style={{margin:'-6px 0 12px'}}>{tr('ไม่พบคำที่ตรงกันพอดี จึงแสดงผลที่ใกล้เคียงที่สุดแทน (ตรวจตัวสะกดได้)')}</p>}{results.error?<p className="error-box">{(results.error as Error).message}</p>:<div className="search-results">{found.slice((page-1)*8,page*8).map(r=><button className="card search-result" key={r.chunk_id} onClick={()=>onPreview(r.document_id,{page:r.page,quote:r.snippet})}><FileIcon name={r.name}/><div><h3>{localName(r)}{r.rerank_score!==undefined&&<small className="ml-2 rounded-full bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary" title={tr('ความตรงกับคำค้นตามการประเมินของโมเดลจัดอันดับ')}>{tr('ตรงกับคำค้น {p}%',{p:Math.round(r.rerank_score*100)})}</small>}{r.kind==='image'&&<ImageIcon size={14} className="ml-2 inline text-muted-foreground" aria-label={tr('ภาพในเอกสาร')}/>}</h3><p><Snippet text={r.snippet} query={search}/></p><span><FolderOpen size={14}/>{kbs.find(k=>k.id===((r as Citation&{knowledge_base_id:string}).knowledge_base_id))?.name||tr('เอกสารองค์กร')}<span>·</span>{tr('หน้า {page}',{page:(pagesOf.get(r.document_id)||[r.page]).join(', ')})}<span>·</span>{tr('ดูแหล่งข้อมูล')}</span></div>{r.kind==='image'?<div className="document-thumbnail has-picture"><img src={`/api/chunks/${r.chunk_id}/image`} alt={tr('ภาพในเอกสาร')} loading="lazy"/></div>:<div className="document-thumbnail"><span>AI Knowledge Hub</span><strong>{r.name.replace(/\.[^.]+$/,'')}</strong><i/><i/><i/></div>}<ArrowUpRight size={19}/></button>)}{!found.length&&<Empty icon={Search} title={tr('ยังไม่พบข้อมูลที่ตรงกัน')} text={tr('ตรวจตัวสะกด ลองใช้คำที่สั้นลง หรือเลือกทุกคลังความรู้และทุกประเภทไฟล์ (ค้นหาได้เฉพาะเอกสารที่ประมวลผลเสร็จและคุณมีสิทธิ์เข้าถึง)')}/>}<Pagination page={page} setPage={setPage} total={found.length}/></div>}</>:<div className="card search-start"><Search size={42}/><h2>{tr('ความรู้ที่คุณต้องการ อยู่ใกล้แค่คำค้น')}</h2><p>{tr('ค้นหาด้วยคำสำคัญ หรือใช้ Hybrid เพื่อรวมการค้นหาข้อความและเวกเตอร์')}</p><div>{[tr('นโยบายการทำงาน'),tr('แผนกลยุทธ์'),tr('ความปลอดภัย')].map(v=><button key={v} onClick={()=>{setQ(v);setSearch(v)}}>{v}<ArrowUpRight size={14}/></button>)}</div></div>}{!search&&<><div className="section-heading" style={{marginTop:20}}><h2>{tr('เอกสารทั้งหมด')} <em>{everything.length}</em> {tr('รายการ')}</h2><span className="muted small">{tr('เฉพาะเอกสารที่คุณมีสิทธิ์เข้าถึง')}</span></div><div className="search-results" data-testid="all-documents">{everything.slice((page-1)*8,page*8).map(d=><button className="card search-result" key={d.id} onClick={()=>onPreview(d.id)}><FileIcon name={d.name}/><div><h3>{d.name}</h3><span><FolderOpen size={14}/>{kbName(d.knowledge_base_id)}<span>·</span>{sizeText(d.size)}<span>·</span>{date(d.created_at)}{d.status!=='ready'&&<><span>·</span><Status value={d.status}/></>}</span></div><div className="document-thumbnail"><span>AI Knowledge Hub</span><strong>{d.name.replace(/\.[^.]+$/,'')}</strong><i/><i/><i/></div><ArrowUpRight size={19}/></button>)}{!everything.length&&<Empty icon={FolderOpen} title={tr('ยังไม่มีเอกสาร')} text={tr('ยังไม่มีเอกสารตามตัวกรองนี้ หรือคุณยังไม่มีสิทธิ์เข้าถึงเอกสารใด')}/>}<Pagination page={page} setPage={setPage} total={everything.length}/></div></>}</>
}

function Metric({icon:Icon,title,value,color='blue',note=tr('ข้อมูลจากระบบจริง')}:{icon:LucideIcon;title:string;value:string;color?:string;note?:string}){return <div className="card metric"><IconBox icon={Icon} color={color}/><div><p>{title}</p><strong>{value}</strong><small>{note}</small></div></div>}
type Dept={id:string;name:string;name_en?:string;members:number;active_members:number;admins:string[]};
function Organizations({user,notify,refresh}:{user:User;notify:(s:string)=>void;refresh:()=>void}){const confirm=useConfirm();
 const qc=useQueryClient();const q=useQuery({queryKey:['orgs'],queryFn:()=>api<Org[]>('/admin/organizations')});const depts=useQuery({queryKey:['departments'],queryFn:()=>api<Dept[]>('/team/departments')});
 const org=(q.data||[]).find(o=>o.id===user.tenant_id);const [edit,setEdit]=useState<Partial<Org>|null>(null);const [dept,setDept]=useState<Partial<Dept>|null>(null);const [selected,setSelected]=useState<Dept|null>(null);const [busy,setBusy]=useState(false);
 const run=async(fn:()=>Promise<unknown>,ok:string,done?:()=>void)=>{setBusy(true);try{await fn();qc.invalidateQueries({queryKey:['departments']});qc.invalidateQueries({queryKey:['team']});done?.();notify(ok)}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
 const save=async(e:FormEvent)=>{e.preventDefault();if(!edit?.id)return;const off=(edit.status||'active')!=='active';if(!await confirm({title:tr('บันทึกข้อมูลองค์กร'),text:off?tr('การเปลี่ยนสถานะองค์กรเป็นไม่ใช้งานจะทำให้ผู้ใช้ทั้งองค์กรเข้าสู่ระบบไม่ได้'):tr('ยืนยันการบันทึกข้อมูลองค์กร?'),danger:off}))return;setBusy(true);try{const body={name:edit.name,status:edit.status||'active',quota:edit.quota??10000};await api('/admin/organizations/'+edit.id,{method:'PUT',body:JSON.stringify(body)});setEdit(null);refresh();notify(tr('บันทึกข้อมูลองค์กรแล้ว'))}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
 const saveDept=(e:FormEvent)=>{e.preventDefault();if(!dept)return;run(()=>api('/team/departments'+(dept.id?'/'+dept.id:''),{method:dept.id?'PUT':'POST',body:JSON.stringify({name:dept.name,name_en:dept.name_en||''})}),dept.id?tr('เปลี่ยนชื่อฝ่ายแล้ว'):tr('สร้างฝ่ายแล้ว'),()=>setDept(null))};
 const remove=async(d:Dept)=>{if(await confirm({title:tr('ลบฝ่าย'),text:tr('ลบฝ่าย "{name}" ใช่หรือไม่ (ลบได้เมื่อไม่มีสมาชิกในฝ่าย)',{name:localName(d)}),danger:true,confirmLabel:tr('ลบฝ่าย')}))run(()=>api('/team/departments/'+d.id,{method:'DELETE'}),tr('ลบฝ่ายแล้ว'),()=>setSelected(null))};
 if(selected)return <><div className="heading-actions" style={{marginBottom:12}}><Button variant="outline" onClick={()=>setSelected(null)}><ArrowRight size={16} style={{transform:'rotate(180deg)'}}/>{tr('กลับไปหน้าองค์กร')}</Button></div><TeamPage user={user} notify={notify} departmentId={selected.id} departmentName={selected.name}/></>;
 return <><Heading title={tr('จัดการองค์กร')} subtitle={tr('ภาพรวมองค์กรและฝ่ายต่าง ๆ เลือกฝ่ายเพื่อจัดการผู้ใช้ในฝ่ายนั้น')} action={<Button onClick={()=>setDept({})}><Plus size={18}/>{tr('เพิ่มฝ่าย')}</Button>}/>
 {q.error&&<p className="error-box">{(q.error as Error).message}</p>}
 {org&&<div className="card padded" style={{marginBottom:20}}><div className="section-heading"><h2><span className="organization-name"><span style={{background:COLORS[0]}}>{org.name[0]}</span><strong>{org.name}</strong></span></h2><Button variant="outline" onClick={()=>setEdit(org)}>{tr('แก้ไของค์กร')}</Button></div><div className="stats-grid three"><div><small className="muted">{tr('ผู้ใช้')}</small><strong style={{display:'block',fontSize:22}}>{fmt(org.users)}</strong></div><div><small className="muted">{tr('เอกสาร')}</small><strong style={{display:'block',fontSize:22}}>{fmt(org.documents)}</strong></div><div><small className="muted">{tr('ค่าใช้จ่าย (USD)')}</small><strong style={{display:'block',fontSize:22}}>{money(org.cost)}</strong></div></div><p className="muted small" style={{marginTop:10}}>{tr('สถานะ')} <Status value={org.status}/></p></div>}
 <div className="card"><div className="table-toolbar"><h3>{tr('ฝ่ายทั้งหมด')} <em>{depts.data?.length||0}</em></h3></div><div className="table-scroll"><table><thead><tr><th>{tr('ฝ่าย')}</th><th>{tr('สมาชิก')}</th><th>{tr('ผู้ดูแลฝ่าย')}</th><th>{tr('จัดการ')}</th></tr></thead><tbody>{(depts.data||[]).map(d=><tr key={d.id}><td><strong>{localName(d)}</strong>{otherName(d)&&<small className="muted block">{otherName(d)}</small>}</td><td>{fmt(d.members)} <small className="muted">{tr('(ใช้งาน {v1})',{v1:fmt(d.active_members)})}</small></td><td>{d.admins.join(', ')||'-'}</td><td><div className="inline-actions"><Button onClick={()=>setSelected(d)}><Users size={16}/>{tr('จัดการผู้ใช้')}</Button><Button variant="outline" onClick={()=>setDept(d)}>{tr('เปลี่ยนชื่อ')}</Button><Button variant="outline" onClick={()=>remove(d)}>{tr('ลบ')}</Button></div></td></tr>)}</tbody></table></div>{!depts.data?.length&&<Empty title={tr('ยังไม่มีฝ่าย')} text={tr('กด “เพิ่มฝ่าย” เพื่อสร้างฝ่ายแรกขององค์กร')}/>}</div>
 <OrganizationPolicies notify={notify}/>
 {dept&&<Modal title={dept.id?tr('เปลี่ยนชื่อฝ่าย'):tr('เพิ่มฝ่าย')} onClose={()=>setDept(null)}><form className="stack" onSubmit={saveDept}><label>{tr('ชื่อฝ่าย')}<input required maxLength={100} value={dept.name||''} onChange={e=>setDept({...dept,name:e.target.value})}/></label><label>{tr('ชื่อฝ่าย (อังกฤษ)')}<input maxLength={100} value={dept.name_en||''} placeholder="e.g. Human Resources" onChange={e=>setDept({...dept,name_en:e.target.value})}/></label><Button disabled={busy} type="submit"><Check size={17}/>{tr('บันทึก')}</Button></form></Modal>}
 {edit&&<Modal title={tr('แก้ไของค์กร')} onClose={()=>setEdit(null)}><form className="stack" onSubmit={save}><label>{tr('ชื่อองค์กร')}<input value={edit.name||''} required maxLength={200} onChange={e=>setEdit({...edit,name:e.target.value})}/></label><label>{tr('สถานะ')}<Sel value={edit.status} onChange={e=>setEdit({...edit,status:e.target.value})}><option value="active">{tr('ใช้งานปกติ')}</option><option value="pending">{tr('รออนุมัติ')}</option><option value="suspended">{tr('ระงับการใช้งาน')}</option></Sel></label><label>{tr('โควตาคำถามต่อเดือน')}<input type="number" min={0} max={100000000} value={edit.quota} onChange={e=>setEdit({...edit,quota:Number(e.target.value)})}/></label><Button disabled={busy} type="submit"><Check size={17}/>{tr('บันทึกองค์กร')}</Button></form></Modal>}</>
}
function UsersPage({user,notify}:{user:User;notify:(s:string)=>void}){const confirm=useConfirm();
 const qc=useQueryClient();const users=useQuery({queryKey:['users'],queryFn:()=>api<User[]>('/admin/users'),refetchInterval:15000});const orgs=useQuery({queryKey:['orgs'],queryFn:()=>api<Org[]>('/admin/organizations')});const [q,setQ]=useState('');const [open,setOpen]=useState(false);const [page,setPage]=useState(1);const [busy,setBusy]=useState(false);
 const [editingUser,setEditingUser]=useState<User|null>(null);
 const {register,handleSubmit,reset,watch}=useForm<{name:string;name_en?:string;email:string;role:string;password:string;department_id:string}>({defaultValues:{role:'USER'}});const departments=useQuery({queryKey:['departments'],queryFn:()=>api<{id:string;name:string}[]>('/team/departments')});const found=(users.data||[]).filter(u=>(u.name+u.email).toLowerCase().includes(q.toLowerCase()));
 const save=async(v:{role:string;department_id:string})=>{setBusy(true);try{await post('/admin/users',{...v,tenant_id:user.tenant_id,department_id:v.role==='SUPER_ADMIN'?undefined:v.department_id});qc.invalidateQueries();setOpen(false);reset();notify(tr('เพิ่มผู้ใช้แล้ว ส่งมอบรหัสผ่านให้ผู้ใช้ผ่านช่องทางที่ปลอดภัย'))}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
 const toggle=async(u:User)=>{if(!await confirm({title:u.active?tr('ระงับบัญชีผู้ใช้'):tr('เปิดใช้งานบัญชีผู้ใช้'),text:u.active?tr('{name} จะเข้าสู่ระบบไม่ได้และถูกออกจากระบบทันที',{name:u.name}):tr('{name} จะเข้าสู่ระบบได้อีกครั้ง',{name:u.name}),danger:u.active}))return;try{await post('/admin/users/'+u.id+'/toggle',{});qc.invalidateQueries();notify(tr('เปลี่ยนสถานะผู้ใช้แล้ว'))}catch(e){notify((e as Error).message)}};
 return <><Heading title={tr('จัดการผู้ใช้งาน')} subtitle={tr('จัดการสมาชิก บทบาท และการเข้าถึงของแต่ละองค์กร')} action={<Button onClick={()=>setOpen(true)}><Plus size={18}/>{tr('เพิ่มผู้ใช้')}</Button>}/><div className="card"><div className="table-toolbar"><h3>{tr('ผู้ใช้งานทั้งหมด')} <em>{users.data?.length||0}</em></h3><div className="input-icon"><Search size={17}/><input placeholder={tr('ค้นหาชื่อหรืออีเมล...')} value={q} onChange={e=>{setQ(e.target.value);setPage(1)}} aria-label={tr('ค้นหาผู้ใช้')}/></div></div><div className="table-scroll"><table><thead><tr><th>{tr('ผู้ใช้งาน')}</th><th>{tr('องค์กร')}</th><th>{tr('บทบาท')}</th><th>{tr('สถานะ')}</th><th>{tr('จัดการ')}</th></tr></thead><tbody>{found.slice((page-1)*8,page*8).map(u=><tr key={u.id}><td><div className="user-cell"><span className="relative"><span className="avatar small-avatar">{u.name[0]}</span>{u.online&&<span role="img" aria-label={tr('กำลังใช้งาน')} title={tr('กำลังใช้งานอยู่')} className="absolute -right-0.5 -bottom-0.5 size-2.5 rounded-full bg-emerald-500 ring-2 ring-background"/>}</span><span><strong>{localName(u)}</strong><small>{otherName(u)?otherName(u)+' · ':''}{u.email}</small></span></div></td><td>{orgs.data?.find(o=>o.id===u.tenant_id)?.name}</td><td><span className="plan-tag">{u.role}</span></td><td><Status value={u.active?'active':'suspended'}/></td><td><div className="inline-actions"><Button variant="outline" onClick={()=>setEditingUser(u)}>{tr('บทบาท')}</Button><Button variant="outline" onClick={()=>toggle(u)}>{u.active?tr('ระงับบัญชี'):tr('เปิดใช้งาน')}</Button></div></td></tr>)}</tbody></table></div>{!found.length&&<Empty title={tr('ไม่พบผู้ใช้')} text={tr('เพิ่มผู้ใช้ใหม่หรือเปลี่ยนคำค้น')}/>}<Pagination total={found.length} page={page} setPage={setPage}/></div>{editingUser&&<UserEditor user={editingUser} onClose={()=>setEditingUser(null)} notify={notify}/>} {open&&<Modal title={tr('เพิ่มผู้ใช้งาน')} onClose={()=>setOpen(false)}><form className="stack" onSubmit={handleSubmit(save)}><label>{tr('ชื่อผู้ใช้งาน')}<input required maxLength={100} {...register('name')}/></label><label>{tr('ชื่อผู้ใช้งาน (อังกฤษ)')}<input maxLength={100} placeholder="e.g. Somchai Jaidee" {...register('name_en')}/></label><label>{tr('อีเมล')}<input type="email" required {...register('email')}/></label><label>{tr('บทบาท')}<Sel {...register('role')}>{ROLES.map(r=><option key={r} value={r}>{roleLabel(r)}</option>)}</Sel></label>{watch('role')!=='SUPER_ADMIN'&&<label>{tr('ฝ่าย')}<Sel required {...register('department_id')}><option value="">{tr('เลือกฝ่าย')}</option>{departments.data?.map(d=><option value={d.id} key={d.id}>{localName(d)}</option>)}</Sel></label>}<label>{tr('รหัสผ่านเริ่มต้น (อย่างน้อย 12 ตัวอักษร)')}<input type="password" minLength={12} maxLength={200} required autoComplete="new-password" {...register('password')}/></label><Button disabled={busy} type="submit"><Users size={17}/>{tr('เพิ่มผู้ใช้')}</Button></form></Modal>}</>
}
const periodUnit=(p?:string)=>p==='day'?tr('ต่อวัน'):p==='week'?tr('ต่อสัปดาห์'):tr('ต่อเดือน');
function BudgetMeter({spent,budget,period}:{spent:number;budget:number;period?:string}){
 if(!budget)return <div className="budget"><strong>{tr('ไม่จำกัด')}</strong><small>{tr('ใช้ไป {v1}',{v1:money(spent)})}</small></div>;
 const pct=spent/budget*100;const tone=pct>=100?'over':pct>=80?'warn':'ok';
 return <div className="budget"><div className="budget-top"><strong>{pct<10&&pct>0?pct.toFixed(1):Math.round(pct)}%</strong><span>{money(spent)} / {money(budget)} <small>{periodUnit(period)}</small></span></div><div className="budget-bar" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.min(100,Math.round(pct))} aria-label={tr('สัดส่วนโควตาที่ใช้ไป')}><i className={tone} style={{width:Math.min(100,pct)+'%'}}/></div></div>
}
type TeamUser=User&{monthly_budget:number;budget_period?:'day'|'week'|'month';month_spend:number;created_at:string;departments:string[];departments_en?:string[];requests:number;input_tokens:number;output_tokens:number;cost:number};
function TeamPage({user,notify,departmentId,departmentName}:{user:User;notify:(s:string)=>void;departmentId?:string;departmentName?:string}){const confirm=useConfirm();
 const qc=useQueryClient();const [days,setDays]=useState('30');const [q,setQ]=useState('');const [page,setPage]=useState(1);const [open,setOpen]=useState(false);const [busy,setBusy]=useState(false);const [editing,setEditing]=useState<TeamUser|null>(null);const [resetting,setResetting]=useState<TeamUser|null>(null);
 const [dept,setDept]=useState(departmentId||'');const [adding,setAdding]=useState(false);
 const team=useQuery({queryKey:['team',days,dept],queryFn:()=>api<TeamUser[]>('/team/users?days='+days+(dept?'&department_id='+dept:''))});
 const depts=useQuery({queryKey:['departments'],queryFn:()=>api<{id:string;name:string}[]>('/team/departments')});
 const mine=depts.data||[];
 const perm=useQuery({queryKey:['team-permissions'],queryFn:()=>api<{manage_users:boolean;reset_password:boolean}>('/team/permissions')});const canManage=perm.data?.manage_users??true;const canReset=perm.data?.reset_password??true;
 const cands=useQuery({queryKey:['team-candidates',dept],queryFn:()=>api<User[]>('/team/departments/'+dept+'/candidates'),enabled:adding&&!!dept});
 const {register,handleSubmit,reset}=useForm<{name:string;name_en?:string;email:string;password:string;department_id:string}>();
 const [quotaFor,setQuotaFor]=useState<TeamUser|null>(null);const quota=useForm<{monthly_budget:number;period:string}>();const rename=useForm<{name:string}>();const pw=useForm<{password:string}>();
 const found=(team.data||[]).filter(u=>(u.name+u.email).toLowerCase().includes(q.toLowerCase()));
 const run=async(fn:()=>Promise<unknown>,ok:string,done?:()=>void)=>{setBusy(true);try{await fn();qc.invalidateQueries({queryKey:['team']});done?.();notify(ok)}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
 const create=(v:{name:string;email:string;password:string;department_id:string})=>run(()=>post('/team/users',{...v,department_id:dept||v.department_id||undefined}),tr('เพิ่มผู้ใช้แล้ว ส่งมอบรหัสผ่านให้ผู้ใช้ผ่านช่องทางที่ปลอดภัย'),()=>{setOpen(false);reset()});
 const total=found.reduce((a,u)=>({requests:a.requests+u.requests,cost:a.cost+u.cost}),{requests:0,cost:0});
 return <><Heading title={departmentName?tr('ฝ่าย{v1}',{v1:departmentName.replace(/^ฝ่าย/,'')}):tr('จัดการผู้ใช้')} subtitle={departmentName?tr('จัดการผู้ใช้และดูการใช้งานของสมาชิกในฝ่ายนี้'):user.role==='SUPER_ADMIN'?tr('จัดการผู้ใช้และดูการใช้งานของทุกฝ่าย'):tr('จัดการผู้ใช้ในฝ่ายที่คุณดูแล และดูการใช้งานของแต่ละคน')} action={<div className="heading-actions">{!departmentId&&mine.length>1&&<Sel aria-label={tr('ฝ่าย')} value={dept} onChange={e=>{setDept(e.target.value);setPage(1)}}><option value="">{tr('ทุกฝ่าย')}</option>{mine.map(g=><option key={g.id} value={g.id}>{localName(g)}</option>)}</Sel>}<Sel aria-label={tr('ช่วงเวลา')} value={days} onChange={e=>setDays(e.target.value)}><option value="7">{tr('7 วันที่ผ่านมา')}</option><option value="30">{tr('30 วันที่ผ่านมา')}</option><option value="90">{tr('90 วันที่ผ่านมา')}</option></Sel>{canManage&&!!dept&&<Button variant="outline" onClick={()=>setAdding(true)}><Users size={18}/>{tr('เพิ่มผู้ใช้ที่มีอยู่')}</Button>}{canManage&&<Button onClick={()=>setOpen(true)}><Plus size={18}/>{tr('เพิ่มผู้ใช้ใหม่')}</Button>}</div>}/>
 <div className="card"><div className="table-toolbar"><h3>{tr('ผู้ใช้')} <em>{found.length}</em> {tr('· คำขอ')} <em>{fmt(total.requests)}</em> {tr('· ค่าใช้จ่าย')} <em>{money(total.cost)}</em></h3><div className="input-icon"><Search size={17}/><input placeholder={tr('ค้นหาชื่อหรืออีเมล...')} value={q} onChange={e=>{setQ(e.target.value);setPage(1)}} aria-label={tr('ค้นหาผู้ใช้')}/></div></div>
 <div className="table-scroll"><table><thead><tr><th>{tr('ผู้ใช้งาน')}</th><th>{tr('แผนก')}</th><th>{tr('คำขอ')}</th><th>{tr('โทเคน (เข้า/ออก)')}</th><th>{tr('ค่าใช้จ่าย')}</th><th>{tr('โควตา (USD)')}</th><th>{tr('สถานะ')}</th><th>{tr('จัดการ')}</th></tr></thead><tbody>{found.slice((page-1)*8,page*8).map(u=><tr key={u.id}><td><div className="user-cell"><span className="relative"><span className="avatar small-avatar">{u.name[0]}</span>{u.online&&<span role="img" aria-label={tr('กำลังใช้งาน')} title={tr('กำลังใช้งานอยู่')} className="absolute -right-0.5 -bottom-0.5 size-2.5 rounded-full bg-emerald-500 ring-2 ring-background"/>}</span><span><strong>{localName(u)}</strong><small>{otherName(u)?otherName(u)+' · ':''}{u.email}</small></span></div></td><td>{deptNames(u).join(', ')||(u.role==='SUPER_ADMIN'?'-':<span className="status red"><i/>{tr('ยังไม่มีฝ่าย')}</span>)}</td><td>{fmt(u.requests)}</td><td>{fmt(u.input_tokens)} / {fmt(u.output_tokens)}</td><td>{money(u.cost)}</td><td><BudgetMeter spent={u.month_spend} budget={u.monthly_budget} period={u.budget_period}/></td><td><Status value={u.active?'active':'suspended'}/></td><td><div className="inline-actions">{canManage&&<Button variant="outline" onClick={()=>{setEditing(u);rename.reset({name:u.name})}}>{tr('แก้ชื่อ')}</Button>}{canManage&&<Button variant="outline" disabled={u.id===user.id} onClick={()=>{setQuotaFor(u);quota.reset({monthly_budget:u.monthly_budget,period:u.budget_period||'month'})}}>{tr('โควตา')}</Button>}{canReset&&<Button variant="outline" onClick={()=>{setResetting(u);pw.reset()}}>{tr('รีเซ็ตรหัสผ่าน')}</Button>}{canManage&&<Button variant="outline" disabled={busy||u.id===user.id} onClick={async()=>{if(await confirm({title:u.active?tr('ระงับบัญชีผู้ใช้'):tr('เปิดใช้งานบัญชีผู้ใช้'),text:u.active?tr('{name} จะเข้าสู่ระบบไม่ได้และถูกออกจากระบบทันที',{name:u.name}):tr('{name} จะเข้าสู่ระบบได้อีกครั้ง',{name:u.name}),danger:u.active}))run(()=>post('/team/users/'+u.id+'/toggle',{}),tr('เปลี่ยนสถานะผู้ใช้แล้ว'))}}>{u.active?tr('ระงับบัญชี'):tr('เปิดใช้งาน')}</Button>}{canManage&&!!dept&&u.id!==user.id&&<Button variant="outline" disabled={busy} onClick={async()=>{if(await confirm({title:tr('นำออกจากฝ่าย'),text:tr('นำ {name} ออกจากฝ่ายนี้? ผู้ใช้ต้องอยู่ในฝ่ายอย่างน้อยหนึ่งฝ่าย',{name:u.name}),danger:true,confirmLabel:tr('นำออก')}))run(()=>api('/team/departments/'+dept+'/members/'+u.id,{method:'DELETE'}),tr('นำออกจากฝ่ายแล้ว'))}}>{tr('นำออกจากฝ่าย')}</Button>}</div></td></tr>)}</tbody></table></div>
 {!found.length&&<Empty title={team.isLoading?tr('กำลังโหลด...'):tr('ไม่พบผู้ใช้')} text={user.role==='DEPARTMENT_ADMIN'&&!mine.length?tr('คุณยังไม่ได้อยู่ในแผนกใด ให้ Super Admin เพิ่มคุณเข้าแผนกก่อน'):tr('เพิ่มผู้ใช้ใหม่หรือเปลี่ยนคำค้น')}/>}<Pagination total={found.length} page={page} setPage={setPage}/></div>
 {open&&<Modal title={tr('เพิ่มผู้ใช้งาน')} onClose={()=>setOpen(false)}><form className="stack" onSubmit={handleSubmit(create)}><label>{tr('ชื่อผู้ใช้งาน')}<input required maxLength={100} {...register('name')}/></label><label>{tr('ชื่อผู้ใช้งาน (อังกฤษ)')}<input maxLength={100} placeholder="e.g. Somchai Jaidee" {...register('name_en')}/></label><label>{tr('อีเมล')}<input type="email" required {...register('email')}/></label>{!dept&&<label>{tr('ฝ่าย')}<Sel required {...register('department_id')}><option value="">{tr('เลือกฝ่าย')}</option>{mine.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</Sel></label>}<label>{tr('รหัสผ่านเริ่มต้น (อย่างน้อย 12 ตัวอักษร)')}<input type="password" minLength={12} maxLength={200} required autoComplete="new-password" {...register('password')}/></label><Button disabled={busy} type="submit"><Users size={17}/>{tr('เพิ่มผู้ใช้')}</Button></form></Modal>}
 {adding&&<Modal title={tr('เพิ่มผู้ใช้ที่มีอยู่เข้าฝ่าย')} onClose={()=>setAdding(false)}>{cands.isLoading?<p className="muted">{tr('กำลังโหลด...')}</p>:!cands.data?.length?<Empty title={tr('ไม่มีผู้ใช้ที่เพิ่มได้')} text={user.role==='SUPER_ADMIN'?tr('ทุกคนอยู่ในฝ่ายนี้แล้ว'):tr('ผู้ดูแลฝ่ายเพิ่มได้เฉพาะผู้ใช้ที่ยังไม่อยู่ในฝ่ายใด')}/>:<div className="stack">{cands.data.map(c=><div key={c.id} className="document-row"><span className="document-title"><strong>{localName(c)}</strong><small>{c.email} · {roleLabel(c.role)}</small></span><Button disabled={busy} onClick={()=>run(()=>post('/team/departments/'+dept+'/members',{user_id:c.id}),tr('เพิ่มเข้าฝ่ายแล้ว'),()=>{qc.invalidateQueries({queryKey:['team-candidates']})})}>{tr('เพิ่ม')}</Button></div>)}</div>}</Modal>}
 {editing&&<Modal title={tr('แก้ไขชื่อผู้ใช้')} onClose={()=>setEditing(null)}><form className="stack" onSubmit={rename.handleSubmit(v=>run(()=>api('/team/users/'+editing.id,{method:'PUT',body:JSON.stringify(v)}),tr('บันทึกแล้ว'),()=>setEditing(null)))}><label>{tr('ชื่อ')}<input required maxLength={100} {...rename.register('name')}/></label><Button disabled={busy} type="submit">{tr('บันทึก')}</Button></form></Modal>}
 {quotaFor&&<Modal title={tr('กำหนดโควตา · {name}',{name:quotaFor.name})} onClose={()=>setQuotaFor(null)}><form className="stack" onSubmit={quota.handleSubmit(async v=>{const n=Math.round((Number(v.monthly_budget)||0)*10000)/10000;if(await confirm({title:tr('กำหนดโควตาการใช้งาน'),text:n?tr('{name} ใช้งานได้ไม่เกิน {v1} {v2} เมื่อครบจะถูกปฏิเสธจนกว่าจะเริ่มรอบใหม่',{name:quotaFor.name,v1:money(n),v2:periodUnit(v.period)}):tr('{name} จะใช้งานได้ไม่จำกัด (ภายใต้งบประมาณขององค์กร)',{name:quotaFor.name})}))await run(()=>api('/team/users/'+quotaFor.id+'/quota',{method:'PUT',body:JSON.stringify({monthly_budget:n,period:v.period||'month'})}),tr('บันทึกโควตาแล้ว'),()=>setQuotaFor(null))})}><label>{tr('รอบโควตา')}<Sel {...quota.register('period')}><option value="day">{tr('รายวัน')}</option><option value="week">{tr('รายสัปดาห์')}</option><option value="month">{tr('รายเดือน')}</option></Sel></label><label>{tr('โควตาต่อรอบ (USD, 0 = ไม่จำกัด)')}<input type="number" min={0} max={1000000} step="0.01" required {...quota.register('monthly_budget')}/></label><div><small className="muted">{tr(quotaFor.budget_period==='day'?'วันนี้ใช้ไปแล้ว':quotaFor.budget_period==='week'?'สัปดาห์นี้ใช้ไปแล้ว':'เดือนนี้ใช้ไปแล้ว')}</small><BudgetMeter spent={quotaFor.month_spend} budget={quotaFor.monthly_budget} period={quotaFor.budget_period}/></div><p className="muted small">{tr('นับจากค่าใช้จ่ายจริงของแชทและการสร้างสื่อ นับใหม่ทุกวัน (00:00 UTC) ทุกวันจันทร์ หรือทุกต้นเดือน ตามรอบที่เลือก')}</p><Button disabled={busy} type="submit">{tr('บันทึกโควตา')}</Button></form></Modal>}
 {resetting&&<Modal title={tr('รีเซ็ตรหัสผ่าน · {name}',{name:resetting.name})} onClose={()=>setResetting(null)}><form className="stack" onSubmit={pw.handleSubmit(async v=>{if(await confirm({title:tr('รีเซ็ตรหัสผ่าน'),text:tr('ตั้งรหัสผ่านใหม่ให้ {name} และออกจากระบบทุกอุปกรณ์ของผู้ใช้นี้',{name:resetting.name})}))await run(()=>post('/team/users/'+resetting.id+'/password',v),tr('รีเซ็ตรหัสผ่านแล้ว ผู้ใช้ต้องเข้าสู่ระบบใหม่'),()=>setResetting(null))})}><label>{tr('รหัสผ่านใหม่ (อย่างน้อย 12 ตัวอักษร)')}<input type="password" minLength={12} maxLength={200} required autoComplete="new-password" {...pw.register('password')}/></label><Button disabled={busy} type="submit">{tr('รีเซ็ตรหัสผ่าน')}</Button></form></Modal>}</>
}
/** Administrator picks which options of an image/video model users may choose in the studio. Nothing restricted = everything the model offers. */
function MediaLimitsField({edit,setEdit}:{edit:Partial<Model>;setEdit:(m:Partial<Model>)=>void}){
 const offered=useQuery({queryKey:['media-options-raw',edit.id],queryFn:()=>api<{resolutions?:string[];aspect_ratios?:string[];durations?:number[]}>('/media/model-options?raw=true&model_id='+encodeURIComponent(edit.id||'')),enabled:!!edit.id,staleTime:60000});
 if(!edit.id)return <p className="info-box">{tr('บันทึกโมเดลก่อน แล้วเปิดตั้งค่าอีกครั้งเพื่อเลือกตัวเลือกที่อนุญาต (ความละเอียด สัดส่วนภาพ ความยาววิดีโอ)')}</p>;
 const groups:[string,string,string[]][]=[['resolutions',tr('ความละเอียดที่อนุญาต'),offered.data?.resolutions||[]],['aspect_ratios',tr('สัดส่วนภาพที่อนุญาต'),offered.data?.aspect_ratios||[]],...(edit.category==='Video'?[['durations',tr('ความยาวที่อนุญาต (วินาที)'),(offered.data?.durations||[]).map(String)] as [string,string,string[]]]:[])].filter(g=>g[2].length>1) as [string,string,string[]][];
 const limits=edit.media_limits||{};
 const toggle=(key:string,all:string[],value:string)=>{const current=limits[key]?.length?limits[key]:all;const next=current.includes(value)?current.filter(v=>v!==value):[...current,value];if(!next.length)return;setEdit({...edit,media_limits:{...limits,[key]:all.every(v=>next.includes(v))?[]:all.filter(v=>next.includes(v))}})};
 if(offered.isLoading)return <p className="small muted">{tr('กำลังอ่านตัวเลือกที่โมเดลรองรับ...')}</p>;
 if(!groups.length)return <p className="small muted">{tr('โมเดลนี้ไม่มีตัวเลือกที่ให้เลือกได้ จึงไม่มีอะไรต้องจำกัด')}</p>;
 return <>{groups.map(([key,label,all])=>{const current=limits[key]?.length?limits[key]:all;return <div className="stack" key={key}><span className="small">{label}</span><div className="ratio-chips" role="group" aria-label={label}>{all.map(v=><button key={v} type="button" aria-pressed={current.includes(v)} className={current.includes(v)?'chip active':'chip'} onClick={()=>toggle(key,all,v)}>{v}</button>)}</div></div>})}<small className="muted">{tr('ผู้ใช้เห็นและเลือกได้เฉพาะตัวเลือกที่เปิดไว้ และระบบปฏิเสธค่าอื่นแม้ส่งตรงผ่าน API ต้องเลือกอย่างน้อย 1 ค่า')}</small></>
}
function ModelsPage({notify}:{notify:(s:string)=>void}){const confirm=useConfirm();
 const qc=useQueryClient();const models=useQuery({queryKey:['models'],queryFn:()=>api<Model[]>('/models')});const [category,setCategory]=useState('LLM');const [edit,setEdit]=useState<Partial<Model>|null>(null);const [busy,setBusy]=useState(false);
 const save=async(e:FormEvent)=>{e.preventDefault();if(!edit)return;if(!await confirm({title:tr('บันทึกการตั้งค่าโมเดล'),text:tr('มีผลกับการเรียกใช้โมเดลนี้ทันที')}))return;setBusy(true);try{const {id,configured,...values}=edit;void configured;await api('/admin/models'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(values)});qc.invalidateQueries({queryKey:['models']});setEdit(null);notify(tr('บันทึกการตั้งค่าโมเดลแล้ว'))}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
 const found=models.data?.filter(m=>m.category===category)||[];
 return <><Heading title={tr('โมเดลและบริการ AI')} subtitle={tr('จัดการโมเดล ปรับราคา และเชื่อมต่อบริการผ่าน LiteLLM Gateway')} action={<Button onClick={()=>setEdit({name:'',provider:'LiteLLM',api_id:'',category,enabled:false,input_price:0,output_price:0})}><Plus size={18}/>{tr('เพิ่มโมเดลใหม่')}</Button>}/><GatewayPanel notify={notify}/><ProvidersPanel notify={notify}/><OpenRouterPanel notify={notify}/><div className="tabs model-tabs">{['LLM','Embedding','Reranker','STT','TTS','Live','Image','Video','Search API'].map(c=><button key={c} className={category===c?'selected':''} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="card"><div className="table-scroll"><table><thead><tr><th>{tr('ชื่อโมเดล')}</th><th>{tr('ผู้ให้บริการ')}</th><th>{tr('ราคา USD / 1M tokens')}</th><th>{tr('สถานะ')}</th><th>{tr('จัดการ')}</th></tr></thead><tbody>{found.map(m=><tr key={m.id}><td><div className="model-cell"><IconBox icon={Boxes} color={m.provider==='Local Demo'?'violet':'blue'}/><span><strong>{m.name}</strong><small>{m.api_id}</small></span></div></td><td><span className="provider-tag">{m.provider}</span></td><td>{money(m.input_price)} / {money(m.output_price)}<small className="muted">{tr('ราคาที่ผู้ดูแลกำหนด{v1}',{v1:m.effort?` · Effort: ${m.effort}`:''})}</small><ModelLimits m={m} block/></td><td><Status value={!m.configured?tr('ยังไม่ตั้งค่า'):m.enabled?'active':tr('ปิดใช้งาน')}/></td><td><Button variant="outline" onClick={()=>setEdit(m)}><SlidersHorizontal size={15}/>{tr('จัดการ')}</Button></td></tr>)}</tbody></table></div>{!found.length&&<Empty icon={Boxes} title={tr('ยังไม่มีโมเดลในหมวดนี้')} text={tr('เพิ่มโมเดลด้วยรหัสที่ตรงกับผู้ให้บริการและ Gateway')}/>}</div><div className="info-box"><ShieldCheck size={19}/><span>{tr('API key เก็บที่ระบบหลังบ้านเท่านั้น โมเดลจะใช้งานได้เมื่อเชื่อมต่อ Gateway และตั้งค่าโมเดลจริงแล้ว เลือกหมวดให้ตรงกับบริการ LLM, Image, Video, STT หรือ TTS ที่ Gateway รองรับ')}</span></div>{edit&&<Modal title={edit.id?tr('ตั้งค่าโมเดล AI'):tr('เพิ่มโมเดล AI')} onClose={()=>setEdit(null)}><form className="stack" onSubmit={save}><label>{tr('ชื่อที่แสดง')}<input required value={edit.name||''} onChange={e=>setEdit({...edit,name:e.target.value})}/></label><label>{tr('ผู้ให้บริการ')}<Sel value={edit.provider} onChange={e=>setEdit({...edit,provider:e.target.value})}><option>LiteLLM</option><option>Google AI</option><option>Local LLM</option><option>OpenRouter</option><option>Local Demo</option></Sel></label><label>{tr('Model ID ใน Gateway')}<input required value={edit.api_id||''} onChange={e=>setEdit({...edit,api_id:e.target.value})} placeholder={tr('กรอก model ID ที่ผู้ให้บริการรองรับจริง')}/></label>{edit.category==='LLM'&&<label>{tr('ระดับการคิด (Effort)')}<Sel value={edit.effort||''} onChange={e=>setEdit({...edit,effort:e.target.value})}><option value="">{tr('ค่าเริ่มต้นของผู้ให้บริการ')}</option><option value="minimal">{tr('minimal · เร็ว/ถูกที่สุด')}</option><option value="low">{tr('low · เร็ว')}</option><option value="medium">{tr('medium · สมดุล')}</option><option value="high">{tr('high · คิดลึก ช้าและแพงกว่า')}</option></Sel><small className="muted">{tr('ใช้กับโมเดลที่รองรับการคิด (reasoning) เท่านั้น โมเดลอื่นอาจปฏิเสธคำขอ')}</small></label>}<label>{tr('หมวดโมเดล')}<Sel value={edit.category} onChange={e=>setEdit({...edit,category:e.target.value})}>{['LLM','Embedding','Reranker','STT','TTS','Image','Video','Search API'].map(c=><option key={c}>{c}</option>)}</Sel></label><div className="form-grid"><label>{tr('ราคา input / 1M tokens')}<input type="number" min={0} step="any" value={edit.input_price} onChange={e=>setEdit({...edit,input_price:Number(e.target.value)})}/></label><label>{tr('ราคา output / 1M tokens')}<input type="number" min={0} step="any" value={edit.output_price} onChange={e=>setEdit({...edit,output_price:Number(e.target.value)})}/></label></div><div className="form-grid"><label>{tr('RPM (คำขอ/นาที)')}<input type="number" min={0} value={edit.rpm||0} onChange={e=>setEdit({...edit,rpm:Number(e.target.value)})}/></label><label>{tr('TPM (โทเคน/นาที)')}<input type="number" min={0} value={edit.tpm||0} onChange={e=>setEdit({...edit,tpm:Number(e.target.value)})}/></label><label>{tr('RPD (คำขอ/วัน)')}<input type="number" min={0} value={edit.rpd||0} onChange={e=>setEdit({...edit,rpd:Number(e.target.value)})}/></label></div>{(edit.category==='Image'||edit.category==='Video')&&<MediaLimitsField edit={edit} setEdit={setEdit}/>}<label className="check-label"><input type="checkbox" checked={edit.enabled||false} onChange={e=>setEdit({...edit,enabled:e.target.checked})}/>{tr('เปิดให้ใช้งาน')}</label><Button disabled={busy} type="submit">{tr('บันทึกการตั้งค่า')}</Button></form></Modal>}</>
}
function Studio({path,notify}:{path:string;notify:(s:string)=>void}){
 const isSpeech=path.endsWith('stt')||path.endsWith('tts');const kind=path.split('/').pop()||'image';const [prompt,setPrompt]=useState('');const [busy,setBusy]=useState(false);const [file,setFile]=useState<File|null>(null);
 const generate=async()=>{setBusy(true);try{await post('/studio/'+kind,{prompt})}catch(e){notify((e as Error).message)}finally{setBusy(false)}};
 return <><Banner title={isSpeech?tr('ถอดเสียง / อ่านออกเสียง'):tr('สร้างภาพ / วิดีโอ')} subtitle={isSpeech?tr('เปลี่ยนเสียงเป็นข้อความ และถ่ายทอดข้อความด้วยเสียง'):tr('สร้างสื่อจากข้อความ เอกสาร หรือบริบทขององค์กร')}/><div className="studio-columns"><div><div className="tabs studio-tabs">{(isSpeech?[['stt',tr('ถอดเสียง'),Mic],['tts',tr('อ่านออกเสียง'),Volume2]]:[['image',tr('สร้างภาพ'),ImageIcon],['video',tr('สร้างวิดีโอ'),Video]]).map(([v,label,Icon])=>{const I=Icon as LucideIcon;return <Link key={String(v)} className={kind===v?'selected':''} href={'/studio/'+v}><I size={20}/>{String(label)}</Link>})}</div><div className="card padded"><div className="section-heading"><h2>{kind==='stt'?tr('ไฟล์เสียงต้นฉบับ'):tr('คำสั่งหรือรายละเอียดที่ต้องการ')}</h2><span className="status amber"><i/>{tr('ยังไม่ตั้งค่า Provider')}</span></div>{kind==='stt'?<label className="dropzone"><Mic size={32}/><strong>{file?.name||tr('เลือกไฟล์เสียง')}</strong><small>{tr('เลือกไฟล์ไว้เตรียมส่งได้ เมื่อเชื่อมต่อผู้ให้บริการแล้ว')}</small><input type="file" accept="audio/*" onChange={e=>setFile(e.target.files?.[0]||null)}/></label>:<><textarea className="studio-prompt" value={prompt} onChange={e=>setPrompt(e.target.value)} maxLength={2000} placeholder={kind==='tts'?tr('พิมพ์ข้อความที่ต้องการให้อ่านออกเสียง...'):tr('อธิบายสิ่งที่ต้องการสร้าง เช่น อาคารสำนักงานสมัยใหม่ บรรยากาศยามเช้า...')}/><div className="text-counter">{prompt.length}/2,000</div></>}<div className="studio-settings"><label>{tr('ผู้ให้บริการ')}<Sel disabled><option>{tr('ยังไม่ได้เชื่อมต่อผู้ให้บริการ')}</option></Sel></label>{!isSpeech&&<label>{tr('อัตราส่วน')}<Sel><option>{tr('16:9 (แนวนอน)')}</option><option>{tr('1:1 (สี่เหลี่ยม)')}</option><option>{tr('9:16 (แนวตั้ง)')}</option></Sel></label>}<Button onClick={generate} disabled={busy||kind!=='stt'&&!prompt.trim()||kind==='stt'&&!file}><Sparkles size={18}/>{kind==='stt'?tr('ถอดเสียง'):kind==='tts'?tr('สร้างเสียง'):kind==='video'?tr('สร้างวิดีโอ'):tr('สร้างภาพ')}</Button></div></div><Section title={tr('ผลลัพธ์จาก AI')}><div className="card studio-empty"><div className="preview-grid-art"><ImageIcon size={62} strokeWidth={1}/></div><h2>{tr('ไอเดียใหม่ของคุณ เริ่มต้นที่นี่')}</h2><p>{tr('ยังไม่มีผลงานที่สร้างจากผู้ให้บริการจริง')}<br/>{tr('เชื่อมต่อ Provider เพื่อเริ่มสร้างสื่อและดูผลลัพธ์')}</p></div></Section></div><aside><div className="card padded studio-info"><IconBox icon={Sparkles} color="violet"/><h3>{tr('สร้างสรรค์อย่างมีบริบท')}</h3><p>{tr('เลือกใช้ AI ที่เหมาะกับงานของคุณ พร้อมติดตามสถานะและค่าใช้จ่ายของแต่ละรายการ')}</p><hr/><h4>{tr('สถานะบริการ')}</h4><div><span>Provider API</span><span className="muted">{tr('ยังไม่ได้ตั้งค่า')}</span></div><div><span>{tr('ประวัติการสร้าง')}</span><span className="muted">{tr('ยังไม่มีรายการ')}</span></div><div><span>{tr('ค่าใช้จ่าย')}</span><strong>$0.00</strong></div><Link className="text-link" href="/super-admin/models">{tr('จัดการโมเดลและบริการ')}<ArrowRight size={15}/></Link></div><div className="studio-tip"><CircleHelp size={18}/><p>{tr('ฟีเจอร์นี้ต้องใช้บัญชีผู้ให้บริการภายนอก ระบบจะไม่แสดงสื่อจำลองเป็นผลลัพธ์จริง')}</p></div></aside></div></>
}
function SystemPage(){
 const q=useQuery({queryKey:['system'],queryFn:()=>api<Record<string,string>>('/system')});
 return <><Heading title={tr('ตั้งค่าระบบ')} subtitle={tr('บริการที่ระบบตั้งค่าเชื่อมต่อไว้ สถานะสุขภาพจริงดูที่หน้าระบบและโครงสร้างพื้นฐาน')}/><div className="system-grid">{q.data&&Object.entries(q.data).map(([k,v],i)=><div className="card system-card" key={k}><IconBox icon={k==='database'?Database:k==='api'?Boxes:ShieldCheck} color={v==='healthy'?'teal':i%2?'violet':'blue'}/><h3>{({api:'API Services',database:tr('ฐานข้อมูล'),storage:tr('จัดเก็บเอกสาร'),vector:tr('ค้นหาเวกเตอร์'),queue:tr('ประมวลผลเอกสาร'),llm:'LLM Gateway',antivirus:'Antivirus',backup:tr('ระบบสำรองข้อมูล')} as Record<string,string>)[k]||k}</h3><Status value={v}/><p>{v==='healthy'?tr('ตรวจสอบการเชื่อมต่อแล้ว'):v.includes('configured')&&!v.includes('not')?tr('ตั้งค่าการเชื่อมต่อแล้ว ยังไม่ใช่ผลตรวจสุขภาพบริการ'):tr('สถานะจากการตั้งค่าระบบ')}</p></div>)}</div>{q.error&&<div className="error-box">{(q.error as Error).message}</div>}</>
}
function Account({user,onLogout}:{user:User;onLogout:()=>void}){return <><Heading title={tr('ตั้งค่าบัญชี')} subtitle={tr('ข้อมูลบัญชีและสิทธิ์การใช้งานของคุณ')}/><div className="card account-card"><span className="avatar account-avatar">{localName(user)[0]}</span><h2>{localName(user)}</h2><p>{user.email}</p><div className="account-fields"><div><span>{tr('บทบาท')}</span><strong>{user.role}</strong></div><div><span>{tr('รหัสองค์กร')}</span><code>{user.tenant_id}</code></div><div><span>{tr('การเข้าสู่ระบบ')}</span><strong>{tr('Local session · 1 วัน')}</strong></div><div><span>{tr('สภาพแวดล้อม')}</span><strong>Production</strong></div></div><Button variant="outline" onClick={onLogout}><LogOut size={17}/>{tr('ออกจากระบบ')}</Button></div></>}
